import { verifyAdmin } from '../lib/auth';
import { forbidden } from 'next/navigation';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <div>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session?.name}!</p>
      <p>This is the admin-only area.</p>
    </div>
  );
}

'use client';

export default function ForbiddenPage() {
  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      height: '100vh',
      fontFamily: 'system-ui, sans-serif',
      textAlign: 'center',
      padding: '20px'
    }}>
      <h1 style={{ fontSize: '6rem', margin: '0', color: '#333' }}>403</h1>
      <h2 style={{ margin: '20px 0', color: '#666' }}>Access Forbidden</h2>
      <p style={{ color: '#888', maxWidth: '400px' }}>
        Sorry, you don&apos;t have permission to access this page. Please contact an administrator if you believe this is a mistake.
      </p>
    </div>
  );
}

'use client';

import { useEffect } from 'react';

export default function Error({
  error,
  reset
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error(error);
  }, [error]);

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      height: '100vh',
      fontFamily: 'system-ui, sans-serif',
      textAlign: 'center',
      padding: '20px'
    }}>
      <h1 style={{ fontSize: '6rem', margin: '0', color: '#333' }}>403</h1>
      <h2 style={{ margin: '20px 0', color: '#666' }}>Access Forbidden</h2>
      <p style={{ color: '#888', maxWidth: '400px', marginBottom: '20px' }}>
        Sorry, you don&apos;t have permission to access this page.
      </p>
      <button
        onClick={reset}
        style={{
          padding: '12px 24px',
          fontSize: '16px',
          cursor: 'pointer',
          backgroundColor: '#0066cc',
          color: 'white',
          border: 'none',
          borderRadius: '4px'
        }}
      >
        Return to Home
      </button>
    </div>
  );
}

export default function AdminLayout({
  children
}: {
  children: React.ReactNode;
}) {
  return (
    <div style={{
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <nav style={{
        marginBottom: '20px',
        padding: '10px',
        backgroundColor: '#f5f5f5',
        borderRadius: '4px'
      }}>
        <strong>Admin Area</strong>
      </nav>
      {children}
    </div>
  );
}
